    }

    .canvas-wrap {
      position: relative;
      width: 100%;
      aspect-ratio: 1 / 1;
      border: 2px solid #334155;
      border-radius: 12px;
      overflow: hidden;
      background: #020617;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
    }

    .overlay {
      position: absolute;
      inset: 0;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 12px;
      padding: 24px;
      text-align: center;
      background: rgba(2, 6, 23, 0.82);
      backdrop-filter: blur(3px);
    }

    .overlay h2 {
      margin: 0;
      font-size: 2rem;
      color: #f8fafc;
    }

    .overlay p {
      margin: 0;
      color: #cbd5e1;
    }

    button {
      margin-top: 8px;
