      margin: 14px 0 0;
      color: #94a3b8;
      font-size: 0.9rem;
      line-height: 1.5;
    }
  </style>
</head>
<body>
  <main class="game-shell">
    <h1>Snake</h1>

    <div class="scoreboard">
      <div>Score: <span id="score">0</span></div>
      <div>High Score: <span id="highScore">0</span></div>
    </div>

    <div class="canvas-wrap">
      <canvas id="gameCanvas" width="400" height="400" aria-label="Snake game board"></canvas>

      <div id="overlay" class="overlay" hidden>
        <h2 id="overlayTitle">Game Over</h2>
        <p id="overlayText"></p>
        <button id="restartBtn" type="button" hidden>Restart Game</button>
      </div>
    </div>

    <p class="help">
      Arrow keys or WASD to move<br />
      Space to pause/resume · R to restart
    </p>
  </main>

  <script>
    const canvas = document.getElementById("gameCanvas");
    const ctx = canvas.getContext("2d");

    const scoreEl = document.getElementById("score");
    const highScoreEl = document.getElementById("highScore");
    const overlay = document.getElementById("overlay");
    const overlayTitle = document.getElementById("overlayTitle");
    const overlayText = document.getElementById("overlayText");
    const restartBtn = document.getElementById("restartBtn");

    const gridCount = 20;
    const tileSize = canvas.width / gridCount;
    const storageKey = "snakeHighScore";

    const DIRECTIONS = {
      up: { x: 0, y: -1 },
      down: { x: 0, y: 1 },
      left: { x: -1, y: 0 },
      right: { x: 1, y: 0 }
    };

    const KEY_TO_DIRECTION = {
      ArrowUp: "up",
      ArrowDown: "down",
      ArrowLeft: "left",
      ArrowRight: "right",
      KeyW: "up",
      KeyA: "left",
      KeyS: "down",
      KeyD: "right",
      w: "up",
      a: "left",
      s: "down",
      d: "right"
    };

    let snake = [];
    let direction = "right";
    let inputQueue = [];
    let food = null;
    let score = 0;
    let highScore = loadHighScore();
    let state = "playing";
    let wonGame = false;

    let lastTime = 0;
    let accumulator = 0;

    function loadHighScore() {
      try {
        const value = parseInt(localStorage.getItem(storageKey), 10);
        return Number.isFinite(value) && value > 0 ? value : 0;
      } catch (error) {
        return 0;
      }
    }

    function saveHighScore() {
      try {
        localStorage.setItem(storageKey, String(highScore));
      } catch (error) {
        /* localStorage may be unavailable; ignore. */
      }
    }

    function updateScoreboard() {
      scoreEl.textContent = score;
      highScoreEl.textContent = highScore;
    }

    function getMoveInterval() {
      return Math.max(70, 150 - Math.floor(score / 5) * 10);
    }

    function hideOverlay() {
      overlay.hidden = true;
      restartBtn.hidden = true;
    }

    function showOverlay(kind) {
      overlay.hidden = false;

      if (kind === "paused") {
        overlayTitle.textContent = "Paused";
        overlayText.textContent = "Press Space to resume";
        restartBtn.hidden = true;
      } else {
        overlayTitle.textContent = wonGame ? "You Win!" : "Game Over";
        overlayText.textContent = `Score: ${score} • High Score: ${highScore}`;
        restartBtn.hidden = false;
        restartBtn.textContent = "Restart Game";
      }
    }

    function resetGame() {
      snake = [
        { x: 8, y: 10 },
        { x: 7, y: 10 },
        { x: 6, y: 10 },
        { x: 5, y: 10 }
      ];

      direction = "right";
      inputQueue = [];
      score = 0;
      wonGame = false;
      state = "playing";
      accumulator = 0;
      lastTime = performance.now();

      spawnFood();
      updateScoreboard();
      hideOverlay();
      restartBtn.blur();
      draw();
    }

    function spawnFood() {
      const occupied = new Set(snake.map(segment => `${segment.x},${segment.y}`));
      const emptyCells = [];

      for (let y = 0; y < gridCount; y++) {
        for (let x = 0; x < gridCount; x++) {
          if (!occupied.has(`${x},${y}`)) {
            emptyCells.push({ x, y });
          }
        }
      }

      if (emptyCells.length === 0) {
        food = null;
        return false;
      }

      food = emptyCells[Math.floor(Math.random() * emptyCells.length)];
      return true;
    }

    function isOpposite(a, b) {
      return DIRECTIONS[a].x + DIRECTIONS[b].x === 0 &&
             DIRECTIONS[a].y + DIRECTIONS[b].y === 0;
    }

    function queueDirection(nextDirection) {
      const lastDirection = inputQueue.length
        ? inputQueue[inputQueue.length - 1]
        : direction;

      if (nextDirection === lastDirection || isOpposite(nextDirection, lastDirection)) {
        return;
      }

      if (inputQueue.length < 2) {
        inputQueue.push(nextDirection);
      }
    }

    function togglePause() {
      if (state === "playing") {
        state = "paused";
        accumulator = 0;
        showOverlay("paused");
      } else if (state === "paused") {
        state = "playing";
        accumulator = 0;
        lastTime = performance.now();
        hideOverlay();
      }
    }

    function endGame(won) {
      state = "gameover";
      wonGame = won;
      accumulator = 0;
      showOverlay("gameover");
    }

    function update() {
      if (inputQueue.length > 0) {
        direction = inputQueue.shift();
      }

      const head = snake[0];
      const vector = DIRECTIONS[direction];
      const newHead = {
        x: head.x + vector.x,
        y: head.y + vector.y
      };

      if (
        newHead.x < 0 || newHead.x >= gridCount ||
        newHead.y < 0 || newHead.y >= gridCount
      ) {
        endGame(false);
        return;
      }

      const eating = food && newHead.x === food.x && newHead.y === food.y;
      const bodyToCheck = eating ? snake : snake.slice(0, -1);

      if (bodyToCheck.some(segment => segment.x === newHead.x && segment.y === newHead.y)) {
        endGame(false);
        return;
      }

      snake.unshift(newHead);

      if (eating) {
        score++;

        if (score > highScore) {
          highScore = score;
          saveHighScore();
        }

        updateScoreboard();

        if (!spawnFood()) {
          endGame(true);
        }
      } else {
        snake.pop();
      }
    }

    function roundedRect(x, y, width, height, radius) {
      const r = Math.min(radius, width / 2, height / 2);

      ctx.beginPath();
      ctx.moveTo(x + r, y);
      ctx.arcTo(x + width, y, x + width, y + height, r);
      ctx.arcTo(x + width, y + height, x, y + height, r);
      ctx.arcTo(x, y + height, x, y, r);
      ctx.arcTo(x, y, x + width, y, r);
      ctx.closePath();
    }

    function drawBoard() {
      ctx.fillStyle = "#020617";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.strokeStyle = "rgba(148, 163, 184, 0.08)";
      ctx.lineWidth = 1;
      ctx.beginPath();

      for (let i = 0; i <= gridCount; i++) {
        const pos = i * tileSize + 0.5;
        ctx.moveTo(pos, 0);
        ctx.lineTo(pos, canvas.height);
        ctx.moveTo(0, pos);
        ctx.lineTo(canvas.width, pos);
      }

      ctx.stroke();
    }

    function drawFood() {
      if (!food) return;

      const cx = food.x * tileSize + tileSize / 2;
      const cy = food.y * tileSize + tileSize / 2;

      ctx.fillStyle = "#ef4444";
      ctx.beginPath();
      ctx.arc(cx + 1, cy + 1, tileSize * 0.34, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = "#f87171";
      ctx.beginPath();
      ctx.arc(cx - 2, cy - 2, tileSize * 0.2, 0, Math.PI * 2);
      ctx.fill();

      ctx.strokeStyle = "#16a34a";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(cx, cy - tileSize * 0.3);
      ctx.lineTo(cx + 3, cy - tileSize * 0.48);
      ctx.stroke();
    }

    function drawEyes(headX, headY) {
      let eyes;

      if (direction === "right") {
        eyes = [
          [headX + tileSize * 0.68, headY + tileSize * 0.35],
          [headX + tileSize * 0.68, headY + tileSize * 0.65]
        ];
      } else if (direction === "left") {
        eyes = [
          [headX + tileSize * 0.32, headY + tileSize * 0.35],
          [headX + tileSize * 0.32, headY + tileSize * 0.65]
        ];
      } else if (direction === "up") {
        eyes = [
          [headX + tileSize * 0.35, headY + tileSize * 0.32],
          [headX + tileSize * 0.65, headY + tileSize * 0.32]
        ];
      } else {
        eyes = [
          [headX + tileSize * 0.35, headY + tileSize * 0.68],
          [headX + tileSize * 0.65, headY + tileSize * 0.68]
        ];
      }

      ctx.fillStyle = "#052e16";
      for (const [x, y] of eyes) {
        ctx.beginPath();
        ctx.arc(x, y, 2, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function drawSnake() {
      for (let i = snake.length - 1; i >= 0; i--) {
        const segment = snake[i];
        const x = segment.x * tileSize;
        const y = segment.y * tileSize;

        ctx.fillStyle = i === 0 ? "#22c55e" : (i % 2 === 0 ? "#16a34a" : "#15803d");
        roundedRect(x + 2, y + 2, tileSize - 4, tileSize - 4, 6);
        ctx.fill();

        if (i === 0) {
          drawEyes(x, y);
        }
      }
    }

    function draw() {
      drawBoard();
      drawFood();
      drawSnake();
    }

    function loop(timestamp) {
      if (!lastTime) lastTime = timestamp;

      let delta = timestamp - lastTime;
      if (delta < 0) delta = 0;
      if (delta > 100) delta = 100;

      lastTime = timestamp;

      if (state === "playing") {
        accumulator += delta;

        while (accumulator >= getMoveInterval() && state === "playing") {
          accumulator -= getMoveInterval();
          update();
        }
      }

      draw();
      requestAnimationFrame(loop);
    }

    window.addEventListener("keydown", event => {
      const key = event.key || "";
      const code = event.code || "";
      const lowerKey = key.length === 1 ? key.toLowerCase() : key;

      if (code === "Space" || key === " ") {
        event.preventDefault();
        if (!event.repeat) togglePause();
        return;
      }

      if (code === "KeyR" || lowerKey === "r") {
        event.preventDefault();
        if (!event.repeat) resetGame();
        return;
      }

      if (key === "Enter" && state === "gameover") {
        event.preventDefault();
        if (!event.repeat) resetGame();
        return;
      }

      const nextDirection = KEY_TO_DIRECTION[code] || KEY_TO_DIRECTION[lowerKey];

      if (nextDirection) {
        event.preventDefault();
        if (state === "playing") {
          queueDirection(nextDirection);
        }
      }
    });

    restartBtn.addEventListener("click", resetGame);

    resetGame();
    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

