  --bg: #0d0d0f;
  --surface: #161618;
  --surface-light: #222225;
  --text: #e0e0e0;
  --text-muted: #888;
  --accent: #ff6b00;
  --accent-glow: rgba(255, 107, 0, 0.3);
  --cyan: #00e5ff;
  --border: #333;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  color: var(--accent);
  text-decoration: none;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Header */
header {
  padding: 20px 0;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  background: rgba(13, 13, 15, 0.9);
  backdrop-filter: blur(10px);
  z-index: 100;
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: 2px;
  color: #fff;
}
.logo span {
  color: var(--accent);
}

nav a {
  margin-left: 20px;
  color: var(--text);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: color 0.3s;
}
nav a:hover {
  color: var(--accent);
}

/* Buttons */
.btn {
  display: inline-block;
  padding: 12px 24px;
  background: var(--accent);
  color: #fff;
  border-radius: 4px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: all 0.3s;
  border: none;
  cursor: pointer;
}
.btn:hover {
  background: #ff8533;
  box-shadow: 0 0 15px var(--accent-glow);
  transform: translateY(-2px);
}
.btn-outline {
  background: transparent;
  border: 1px solid var(--accent);
  color: var(--accent);
}
.btn-outline:hover {
  background: var(--accent);
  color: #fff;
}

/* Hero */
.hero {
  padding: 80px 0;
  text-align: center;
  background: radial-gradient(circle at center, #1a1a24 0%, var(--bg) 70%);
}

.hero h1 {
  font-size: 4rem;
  font-weight: 900;
  margin-bottom: 10px;
  letter-spacing: -1px;
  background: linear-gradient(to right, #fff, #888);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.hero p {
  font-size: 1.2rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto 40px;
}

.hero .synth-wrapper {
  margin: 40px auto;
  perspective: 1000px;
}
```

