CSS for Synth:
```css
/* Synth Base */
.synth {
  width: 100%;
  max-width: 800px;
  height: 400px;
  background: #151518;
  border: 3px solid #2a2a2e;
  border-radius: 10px;
  box-shadow: 
    0 30px 60px rgba(0,0,0,0.9), 
    inset 0 2px 3px rgba(255,255,255,0.05),
    inset 0 -2px 5px rgba(0,0,0,0.5);
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  position: relative;
}

/* Wood side panels */
.synth::before, .synth::after {
  content: '';
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 20px;
  background: linear-gradient(to right, #3e2723, #5d4037, #3e2723);
  border-radius: 10px 0 0 10px;
  z-index: 10;
  box-shadow: inset 0 0 5px rgba(0,0,0,0.8);
}
.synth::after {
  right: -3px;
  left: auto;
  border-radius: 0 10px 10px 0;
  background: linear-gradient(to left, #3e2723, #5d4037, #3e2723);
}

.synth-top {
  height: 60%;
  padding: 20px 30px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.synth-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid #333;
  padding-bottom: 10px;
}

.synth-brand {
  color: #ff6b00;
  font-family: monospace;
  font-size: 1.5rem;
  font-weight: bold;
  letter-spacing: 4px;
  text-shadow: 0 0 8px rgba(255, 107, 0, 0.4);
}

.synth-screen {
  background: #051505;
  color: #4f4;
  font-family: monospace;
  font-size: 0.9rem;
  padding: 5px 15px;
  border-radius: 3px;
  border: 1px solid #222;
  box-shadow: inset 0 2px 5px rgba(0,0,0,1);
  text-shadow: 0 0 5px rgba(0,255,0,0.5);
}

.synth-controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 20px;
}

.knob-row, .slider-row {
  display: flex;
  gap: 30px;
}

.knob-group, .slider-group {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.label {
  font-size: 0.65rem;
  color: #888;
  letter-spacing: 1px;
}

/* Knobs */
.knob {
  width: 45px;
  height: 45px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #444, #111);
  box-shadow: 
    0 5px 10px rgba(0,0,0,0.8), 
    inset 0 2px 2px rgba(255,255,255,0.15),
    inset 0 -2px 4px rgba(0,0,0,0.8);
  position: relative;
  border: 1px solid #000;
}
.knob::before {
  content:'';
  position:absolute;
  top: 5%; left: 5%; right: 5%; bottom: 5%;
  border-radius: 50%;
  border: 1px dashed #333;
}
.knob-line {
  position: absolute;
  top: 10%;
  left: 50%;
  width: 3px;
  height: 35%;
  background: var(--cyan);
  transform-origin: 50% 100%;
  transform: translateX(-50%) rotate(0deg);
  border-radius: 2px;
  box-shadow: 0 0 5px var(--cyan);
}
.knob-group:nth-child(1) .knob-line { transform: translateX(-50%) rotate(45deg); }
.knob-group:nth-child(2) .knob-line { transform: translateX(-50%) rotate(-60deg); }
.knob-group:nth-child(3) .knob-line { transform: translateX(-50%) rotate(135deg); }
.knob-group:nth-child(4) .knob-line { transform: translateX(-50%) rotate(-15deg); }

/* Sliders */
.slider {
  width: 14px;
  height: 70px;
  background: #000;
  border-radius: 7px;
  position: relative;
  box-shadow: inset 0 2px 6px rgba(0,0,0,1);
  border: 1px solid #222;
}
.slider::after {
  content:'';
  position:absolute;
  top: 5px; bottom: 5px; left: 50%;
  width: 2px;
  background: #222;
  transform: translateX(-50%);
}
.slider-cap {
  position: absolute;
  width: 26px;
  height: 14px;
  background: linear-gradient(to bottom, #ddd, #777);
  left: -7px;
  top: 20px;
  border-radius: 2px;
  box-shadow: 0 3px 6px rgba(0,0,0,0.8), inset 0 1px 1px rgba(255,255,255,0.8);
  z-index: 2;
}
.slider-cap::after {
  content:'';
  position:absolute;
  top: 50%; left: 10%; right: 10%;
  height: 2px;
  background: #333;
  transform: translateY(-50%);
}
.slider-group:nth-child(1) .slider-cap { top: 10px; }
.slider-group:nth-child(2) .slider-cap { top: 35px; }
.slider-group:nth-child(3) .slider-cap { top: 5px; }
.slider-group:nth-child(4) .slider-cap { top: 45px; }

/* Synth Bottom (Keys & Wheels) */
.synth-bottom {
  height: 40%;
  display: flex;
  background: #111;
  border-top: 2px solid #000;
  padding: 0 20px 20px 20px;
}

.pitch-mod {
  width: 80px;
  display: flex;
  gap: 10px;
  padding-top: 10px;
  flex-shrink: 0;
}

.wheel {
  width: 25px;
  flex-grow: 1;
  background: linear-gradient(to right, #222, #333, #222);
  border-radius: 4px;
  border: 1px solid #000;
  box-shadow: inset 0 5px 10px rgba(0,0,0,0.8);
  position: relative;
}
.wheel::after {
  content: '';
  position: absolute;
  top: 20px;
  left: 0; right: 0;
  height: 10px;
  background: #111;
  border-top: 1px solid #444;
  border-bottom: 1px solid #444;
}

.synth-keys {
  flex-grow: 1;
  display: flex;
  padding-top: 10px;
}

.w-key {
  flex: 1;
  background: linear-gradient(to bottom, #fff 90%, #ddd 100%);
  border: 1px solid #999;
  border-radius: 0 0 4px 4px;
  position: relative;
  box-shadow: inset 0 -3px 5px rgba(0,0,0,0.1);
}

.b-key {
  position: absolute;
  top: 0;
  right: -30%;
  width: 60%;
  height: 65%;
  background: linear-gradient(to bottom, #222 0%, #000 90%, #111 100%);
  border-radius: 0 0 3px 3px;
  z-index: 2;
  box-shadow: 0 4px 6px rgba(0,0,0,0.6), inset 0 -2px 2px rgba(255,255,255,0.1);
  border: 1px solid #000;
  border-top: none;
}

/* Hide specific black keys */
.w-key:nth-child(3) .b-key,
.w-key:nth-child(7) .b-key,
.w-key:nth-child(10) .b-key,
.w-key:nth-child(14) .b-key {
  display: none;
}
```

